package q.qedet.hr.attendance.entity;
import jakarta.persistence.*; import lombok.*; import q.qedet.common.model.TimestampedEntity; import q.qedet.employee.entity.Employee; import q.qedet.hr.attendance.model.*; import q.qedet.organization.entity.Organization; import java.time.*; import java.util.UUID;
@Entity @Table(name="hr_attendance_adjustment_requests", indexes=@Index(name="idx_hr_adjustment_org_status",columnList="organization_id,status")) @Getter @Setter @NoArgsConstructor
public class AttendanceAdjustmentRequest extends TimestampedEntity { @ManyToOne(optional=false) @JoinColumn(name="organization_id",nullable=false) private Organization organization; @ManyToOne(optional=false) @JoinColumn(name="employee_id",nullable=false) private Employee employee; @ManyToOne @JoinColumn(name="attendance_id") private AttendanceRecord attendance; @Enumerated(EnumType.STRING) @Column(nullable=false) private AdjustmentRequestType type; @Enumerated(EnumType.STRING) @Column(nullable=false) private AdjustmentRequestStatus status=AdjustmentRequestStatus.PENDING; private Instant requestedCheckIn; private Instant requestedCheckOut; @Column(length=1000) private String reason; private UUID reviewedBy; private Instant reviewedAt; private String reviewReason; }

